package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen0Test {

    private FormElement formElement;

    @Before
    public void setUp() {
        formElement = new FormElement(new Tag("form"),
                "http://example.com", new Attributes());
    }

    @Test
    public void testFormData_EmptyForm() {
        List<Connection.KeyVal> result = formElement.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_TextInput() {
        Element inputElement = new Element(Tag.valueOf("input"), "http://example.com", new Attributes()
                .put("type", "text")
                .put("name", "username")
                .put("value", "testuser"));
        formElement.addElement(inputElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertEquals("username", result.get(0).key());
        assertEquals("testuser", result.get(0).value());
    }

    @Test
    public void testFormData_DisabledInput() {
        Element disabledInput = new Element(Tag.valueOf("input"), "http://example.com", new Attributes()
                .put("type", "text")
                .put("name", "disabledInput")
                .put("value", "should not be included")
                .put("disabled", "disabled"));
        formElement.addElement(disabledInput);

        List<Connection.KeyVal> result = formElement.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_SelectWithoutSelectedOption() {
        Element selectElement = new Element(Tag.valueOf("select"), "http://example.com", new Attributes()
                .put("name", "dropdown"));
        formElement.addElement(selectElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_SelectWithSelectedOption() {
        Element selectElement = new Element(Tag.valueOf("select"), "http://example.com", new Attributes()
                .put("name", "dropdown"));
        selectElement.parser().appendElement(Tag.valueOf("option"), new Attributes().put("selected", "selected").put("value", "option1"));
        selectElement.parser().appendElement(Tag.valueOf("option"), new Attributes().put("value", "option2"));
        formElement.addElement(selectElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertEquals("dropdown", result.get(0).key());
        assertEquals("option1", result.get(0).value());
    }

    @Test
    public void testFormData_CheckboxUnchecked() {
        Element checkboxElement = new Element(Tag.valueOf("input"), "http://example.com", new Attributes()
                .put("type", "checkbox")
                .put("name", "checkbox"));
        formElement.addElement(checkboxElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_CheckboxCheckedWithValue() {
        Element checkboxElement = new Element(Tag.valueOf("input"), "http://example.com", new Attributes()
                .put("type", "checkbox")
                .put("name", "checkbox")
                .put("value", "checkedValue")
                .put("checked", "checked"));
        formElement.addElement(checkboxElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertEquals("checkbox", result.get(0).key());
        assertEquals("checkedValue", result.get(0).value());
    }

    @Test
    public void testFormData_CheckboxCheckedWithNoValue() {
        Element checkboxElement = new Element(Tag.valueOf("input"), "http://example.com", new Attributes()
                .put("type", "checkbox")
                .put("name", "checkbox")
                .put("checked", "checked"));
        formElement.addElement(checkboxElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertEquals("checkbox", result.get(0).key());
        assertEquals("on", result.get(0).value());
    }

    @Test
    public void testFormData_RadioUnchecked() {
        Element radioElement = new Element(Tag.valueOf("input"), "http://example.com", new Attributes()
                .put("type", "radio")
                .put("name", "radio"));
        formElement.addElement(radioElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_RadioCheckedWithValue() {
        Element radioElement = new Element(Tag.valueOf("input"), "http://example.com", new Attributes()
                .put("type", "radio")
                .put("name", "radio")
                .put("value", "radioValue")
                .put("checked", "checked"));
        formElement.addElement(radioElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertEquals("radio", result.get(0).key());
        assertEquals("radioValue", result.get(0).value());
    }

    @Test
    public void testFormData_RadioCheckedWithNoValue() {
        Element radioElement = new Element(Tag.valueOf("input"), "http://example.com", new Attributes()
                .put("type", "radio")
                .put("name", "radio")
                .put("checked", "checked"));
        formElement.addElement(radioElement);

        List<Connection.KeyVal> result = formElement.formData();
        assertEquals(1, result.size());
        assertEquals("radio", result.get(0).key());
        assertEquals("on", result.get(0).value());
    }
}
